What is printed by this loop?
```python
class Countdown:
    def __init__(self, start):
        self.current = start
    def __iter__(self):
        return self
    def __next__(self):
        if self.current <= 0:
            raise StopIteration
        self.current -= 1
        return self.current + 1

for n in Countdown(3):
    print(n)
```

What does this print?

```python
import functools

def tag(name):
    def deco(fn):
        print(f"decorating with {name}")
        @functools.wraps(fn)
        def wrapper(*a, **k):
            print(f"enter {name}")
            return fn(*a, **k)
        return wrapper
    return deco

@tag("A")
@tag("B")
def f():
    print("body")

f()
```

